{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "After i.v. administration in rats, isovitexin was detected in brain tissue at 14.74 ng/mL, demonstrating transfer across the blood-brain barrier after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Guanosine entered the CNS within 7.5 minutes after systemic administration and produced dose-dependent increases in CSF after oral dosing, indicating meaningful BBB/CNS access via transporter-mediated uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In humans, vidarabine (ara-A) achieved a mean CSF-to-plasma ratio of 35% after systemic therapy, indicating satisfactory CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved evidence molecules show direct CNS access after systemic administration, with brain or CSF detection in rats, mice, non-human primates, pigs, and humans. No retrieved record argues against meaningful CNS access.",
  "evidence_gaps": [
    "Most records provide brain or CSF concentrations rather than formal unbound brain-to-plasma ratios, but direct systemic CNS detection is sufficient for the endpoint.",
    "One record involved TBI-induced BBB disruption and was not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

